const { quote } = require('/work/index.js');

const CONTROL_PAYLOAD = 'ordinary-token';
const EXPLOIT_PAYLOAD = '`:;owned`:;';

function hasUnescapedBacktick(value) {
  for (let index = 0; index < value.length; index += 1) {
    if (value[index] !== '`') continue;
    let slashes = 0;
    for (let cursor = index - 1; cursor >= 0 && value[cursor] === '\\'; cursor -= 1) slashes += 1;
    if (slashes % 2 === 0) return true;
  }
  return false;
}

function run_target(payload) {
  const rendered = quote([payload]);
  if (payload === CONTROL_PAYLOAD) return rendered === CONTROL_PAYLOAD;
  return !hasUnescapedBacktick(rendered);
}

module.exports = { CONTROL_PAYLOAD, EXPLOIT_PAYLOAD, run_target };
